const state={articles:[],category:'すべて',query:'',favorites:new Set(JSON.parse(localStorage.getItem('deliveryNewsFavorites')||'[]'))};
const $=s=>document.querySelector(s);const grid=$('#newsGrid'),tpl=$('#cardTemplate');
const escapeText=t=>String(t??'');
function fmtDate(value){const d=new Date(value);return Number.isNaN(d.getTime())?'日時不明':new Intl.DateTimeFormat('ja-JP',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)}
function filtered(){return state.articles.filter(a=>{const category=state.category==='すべて'||(state.category==='お気に入り'?state.favorites.has(a.id):a.category===state.category);const q=state.query.toLowerCase();return category&&(!q||`${a.title} ${a.description} ${a.source}`.toLowerCase().includes(q))})}
function render(){const items=filtered();grid.replaceChildren();$('#totalCount').textContent=state.articles.length;$('#resultCount').textContent=`${items.length}件を表示`;$('#sectionTitle').textContent=state.category==='すべて'?'最新ニュース':state.category;$('#sectionKicker').textContent=state.category==='お気に入り'?'SAVED':'LATEST';$('#emptyState').hidden=items.length>0;
  items.forEach(a=>{const node=tpl.content.cloneNode(true);node.querySelector('.category').textContent=a.category;node.querySelector('time').textContent=fmtDate(a.publishedAt);node.querySelector('h3').textContent=escapeText(a.title);node.querySelector('.description').textContent=escapeText(a.description||'記事の詳しい内容は配信元でご確認ください。');node.querySelector('.source').textContent=escapeText(a.source);const link=node.querySelector('.read');link.href=a.url;const fav=node.querySelector('.favorite');const saved=state.favorites.has(a.id);fav.textContent=saved?'★':'☆';fav.classList.toggle('saved',saved);fav.setAttribute('aria-label',saved?'お気に入りから削除':'お気に入りに追加');fav.addEventListener('click',()=>toggleFavorite(a.id));grid.append(node)})}
function toggleFavorite(id){state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);localStorage.setItem('deliveryNewsFavorites',JSON.stringify([...state.favorites]));render()}
async function loadNews(manual=false){const btn=$('#refreshBtn');if(manual){btn.classList.add('loading');btn.textContent='確認中…'}try{const res=await fetch(`data/news.json?v=${Date.now()}`);if(!res.ok)throw new Error('load failed');const data=await res.json();state.articles=data.articles||[];$('#updatedAt').textContent=`最終更新 ${fmtDate(data.updatedAt)}`;render()}catch(e){$('#updatedAt').textContent='更新情報を取得できません';grid.innerHTML='<div class="empty"><b>ニュースを読み込めませんでした</b><span>時間をおいて、もう一度お試しください。</span></div>'}finally{btn.classList.remove('loading');btn.textContent='↻ 最新情報を確認'}}
$('#categoryTabs').addEventListener('click',e=>{if(!e.target.matches('button'))return;document.querySelectorAll('.tabs button').forEach(b=>b.classList.remove('active'));e.target.classList.add('active');state.category=e.target.dataset.category;render()});
$('#searchInput').addEventListener('input',e=>{state.query=e.target.value.trim();render()});$('#refreshBtn').addEventListener('click',()=>loadNews(true));loadNews();
